```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    /// Drop every item whose `id` is already recorded in the `seen` store.
    /// The `id` is a parser-computed digest, not feed-chosen text, so it is
    /// safe to use as a lookup key. Items are otherwise passed through unchanged.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
